param([string]$BenchmarkRepo="D:\Dev\LotSizingDataModel.Benchmarks")
Set-StrictMode -Version Latest;$ErrorActionPreference="Stop";$g=Join-Path $BenchmarkRepo "catalog\global";$registryPath=Join-Path $g "GLOBAL-BENCHMARK-REGISTRY-v0.22.0.csv";$trustPath=Join-Path $g "GLOBAL-NORMALIZED-TRUST-v0.22.0.csv";$baseline="v0.22.0";if(-not(Test-Path -LiteralPath $registryPath -PathType Leaf)){ $registryPath=Join-Path $g "GLOBAL-BENCHMARK-REGISTRY-v0.21.0.csv";$trustPath=Join-Path $g "GLOBAL-NORMALIZED-TRUST-v0.21.0.csv";$baseline="v0.21.0"};if(-not(Test-Path -LiteralPath $registryPath -PathType Leaf)-or-not(Test-Path -LiteralPath $trustPath -PathType Leaf)){throw "Neither v0.22.0 nor v0.21.0 validated baseline is available."};$r=@(Import-Csv -LiteralPath $registryPath);$t=@(Import-Csv -LiteralPath $trustPath);if($r.Count -ne 7905 -or $t.Count -ne 7905){throw "Global row invariant failed."};if(@($r|Group-Object global_instance_id|Where-Object Count -gt 1).Count -ne 0){throw "Duplicate global IDs."};if(@($r|Where-Object{[string]::IsNullOrWhiteSpace($_.fingerprint)}).Count -ne 0){throw "Missing fingerprints."};if(@($r|Group-Object fingerprint|Where-Object Count -gt 1).Count -ne 0){throw "Duplicate fingerprints."};$allowed=@("NO_REFERENCE_KNOWN","LITERATURE_REFERENCE_UNVERIFIED","LITERATURE_BEST_REPORTED","REFERENCE_WITH_LOWER_BOUND","COMPLETE_SOLUTION_UNCHECKED","CHECKER_VERIFIED_FEASIBLE","VERIFIED_PROVEN_OPTIMAL");if(@($t|Where-Object{$_.normalized_trust_status -notin $allowed}).Count -ne 0){throw "Unknown trust status."};Write-Host "GLOBAL_RELEASE_V0.23.0_VALID";Write-Host("BASELINE|"+$baseline);Write-Host "ROWS|7905";Write-Host "GLOBAL_IDS|UNIQUE";Write-Host "DUPLICATE_FINGERPRINTS|0";Write-Host "TRUST_TAXONOMY|VALID"
